{
  "title": "AI toolkit discussion, diploma cover fees, and PC case GPU hack",
  "topics": [
    {
      "id": "ai-capabilities",
      "title": "AI capabilities and need for toolkits",
      "claims": [
        {
          "text": "AI systems cannot be inherently intelligent; complex abilities they exhibit are provided by toolkits and ready-made solutions.",
          "evidence": [1]
        },
        {
          "text": "No one wants AI to be smart because people themselves don't know how to handle it.",
          "evidence": [2]
        },
        {
          "text": "Older AI models are likely unable to handle tasks due to limited context windows.",
          "evidence": [3]
        },
        {
          "text": "Toolkits can give a large performance boost but cannot compensate for a model's lack of basic capabilities.",
          "evidence": [8]
        },
        {
          "text": "ChatGPT 3 has 175 B parameters, but a better metric based on active parameters exists; older models were trained on everything without task focus, whereas modern models aim to extract more from fewer parameters and are sometimes trained for specific tasks.",
          "evidence": [14]
        }
      ]
    },
    {
      "id": "diploma-cover-fee",
      "title": "Costs and perception of diploma covers",
      "claims": [
        {
          "text": "Someone named Bogdan asks for 650 UAH for a diploma cover.",
          "evidence": [23]
        },
        {
          "text": "One participant paid 47 UAH for a diploma cover.",
          "evidence": [24]
        },
        {
          "text": "Another participant paid 30 UAH for a diploma cover.",
          "evidence": [25]
        },
        {
          "text": "Diploma covers are considered paper waste if provided without charge.",
          "evidence": [26]
        },
        {
          "text": "The diploma cover features a unique KPI seal.",
          "evidence": [27]
        },
        {
          "text": "No one is expected to take the diploma cover.",
          "evidence": [28]
        },
        {
          "text": "People will look at the diploma cover three times in life: when receiving the diploma, when photographing it, and when translating documents later.",
          "evidence": [29]
        }
      ]
    },
    {
      "id": "pc-case-mod",
      "title": "Fitting multiple GPUs in a small PC case",
      "claims": [
        {
          "text": "A small PC case that normally holds only one small GPU can accommodate three GPUs by using straps and brute force.",
          "evidence": [30]
        }
      ]
    }
  ],
  "decisions": [
    {
      "text": "Fit three small GPUs in a small PC case by using straps and applying brute force.",
      "evidence": [30]
    }
  ],
  "openQuestions": [
    {
      "text": "How many participants have paid money for diploma covers?",
      "evidence": [22]
    }
  ]
}
